import { createHash } from "node:crypto"; import { mkdir, readFile, rename, writeFile, readdir } from "node:fs/promises"; import path from "node:path"; import type { AdRunnerManifest, BootstrapConfiguration } from "../specification/types.js";
const safe=(s:string)=>{if(!/^[a-zA-Z0-9._-]+$/.test(s)) throw new Error(`Invalid site id ${s}`); return s;};
export async function publishManifest(dataDir:string, manifest:AdRunnerManifest){ const site=safe(manifest.site); const version=createHash("sha256").update(JSON.stringify(manifest)).digest("hex").slice(0,8); manifest.version=version; const dir=path.join(dataDir,"sites",site); const mdir=path.join(dir,"manifests"); await mkdir(mdir,{recursive:true}); const tmp=path.join(mdir,`${version}.json.tmp`); const final=path.join(mdir,`${version}.json`); await writeFile(tmp,JSON.stringify(manifest,null,2)); await rename(tmp,final); const boot:BootstrapConfiguration={spec:manifest.spec,site,version,manifest:`/v1/sites/${encodeURIComponent(site)}/manifests/${version}.json`,publishedAt:new Date().toISOString()}; await writeFile(path.join(dir,"bootstrap.json.tmp"),JSON.stringify(boot,null,2)); await rename(path.join(dir,"bootstrap.json.tmp"),path.join(dir,"bootstrap.json")); await writeFile(path.join(dir,"current"),version); await writeFile(path.join(dir,"health.json"),JSON.stringify({site,version,status:"ok",publishedAt:boot.publishedAt},null,2)); return boot; }
export async function listVersions(dataDir:string,site:string){try{return (await readdir(path.join(dataDir,"sites",safe(site),"manifests"))).filter((f:string)=>f.endsWith(".json")).map((f:string)=>f.replace(/\.json$/,"")).sort();}catch{return[]}}
export async function rollback(dataDir:string,site:string,version:string){ const dir=path.join(dataDir,"sites",safe(site)); await readFile(path.join(dir,"manifests",`${version}.json`)); const boot={spec:"ad-runner/1",site,version,manifest:`/v1/sites/${encodeURIComponent(site)}/manifests/${version}.json`,publishedAt:new Date().toISOString()}; await writeFile(path.join(dir,"bootstrap.json"),JSON.stringify(boot,null,2)); await writeFile(path.join(dir,"current"),version); return boot; }
